import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"WebAuthn Passkey Dogfood — register-attestation quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/webauthn-passkey-app-register.md","filePath":"quality-reports/auth/webauthn-passkey-app-register.md"}'),i={name:"quality-reports/auth/webauthn-passkey-app-register.md"};function s(d,e,n,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="webauthn-passkey-dogfood-—-register-attestation-quality-report" tabindex="-1">WebAuthn Passkey Dogfood — register-attestation quality report <a class="header-anchor" href="#webauthn-passkey-dogfood-—-register-attestation-quality-report" aria-label="Permalink to &quot;WebAuthn Passkey Dogfood — register-attestation quality report&quot;">​</a></h1><p>Skeleton report for <code>examples/dogfood-webauthn-passkey-app</code> Sub-Issue #856 (v1.21-2a).</p><p>Full mock vs real fidelity numbers are filled in as <code>/manage</code> + <code>/signin</code> land in Sub-Issues #857 - #859. This report tracks the register-attestation ceremony only.</p><h2 id="fidelity-axes-register-attestation" tabindex="-1">Fidelity axes (register-attestation) <a class="header-anchor" href="#fidelity-axes-register-attestation" aria-label="Permalink to &quot;Fidelity axes (register-attestation)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-lab/auth</code>)</th><th>real (SimpleWebAuthn + Chrome Virtual Authenticator)</th><th>assertion</th></tr></thead><tbody><tr><td>1. <code>attestationObject</code> shape</td><td>base64url(<code>attestation::&lt;mode&gt;::&lt;credentialId&gt;::&lt;rpId&gt;</code>) — deterministic</td><td>base64url(CBOR) — attestation statement + authenticator data + fmt</td><td>Both encode as base64url; mock string decodes to a canonical mode-tagged marker so structural drift is caught. Real is validated via SimpleWebAuthn <code>verifyRegistrationResponse</code> (Sub-Issue #857).</td></tr><tr><td>2. <code>clientDataJSON</code> shape</td><td>base64url(JSON) with <code>type=webauthn.create</code>, normalized base64url challenge, origin = <code>https://&lt;rp.id&gt;</code>, <code>crossOrigin=false</code></td><td>same JSON layout, real Uint8Array challenge round-tripped through browser</td><td>JSON shape is identical between mock + real; <code>normalizeChallenge</code> in <code>@kiwa-lab/auth</code> mirrors what a browser encodes.</td></tr><tr><td>3. Signature format</td><td>deterministic fnv-1a base64url (<code>mockSignature</code>)</td><td>ES256 / RS256 / EdDSA base64url (real authenticator)</td><td>Both satisfy the base64url alphabet. Sub-Issue #857 diffs on decoding + verification success rather than byte-equality (mock cannot forge real signatures).</td></tr><tr><td>4. <code>signCount</code> initial value</td><td><code>0</code> (per <code>credentialCreation</code> in <code>packages/auth/src/webauthn/creation.ts</code>)</td><td><code>0</code> (per WebAuthn L3 §6.1.1)</td><td>Both drivers must return exactly <code>0</code> for a freshly minted credential.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/register-attestation.spec.ts</code> — 12 tests, split into three describe blocks: <ul><li><code>mock adapter — register ceremony</code> — 7 tests covering axes 1-4 + persistence + <code>attestation=none</code> + UV=required rejection</li><li><code>real adapter — env-missing skeleton</code> — 2 tests validating the <code>KIWA_WEBAUTHN_ENV_MISSING</code> guard + trace recording when Chrome is not reachable</li><li><code>register route handler — POST /register</code> — 4 tests covering happy path + 400 (missing fields) + 400 (invalid JSON) + 500 (adapter refuses)</li></ul></li></ul><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every test always runs.</li><li><code>DISPLAY</code> unset on Linux — <code>detectRealEnvMissing()</code> returns <code>&#39;DISPLAY unset&#39;</code>, real adapter refuses.</li><li>macOS / Windows without Playwright browsers installed — <code>detectRealEnvMissing()</code> returns <code>KIWA_WEBAUTHN_ENV_MISSING</code> until Sub-Issue #857 wires up <code>chromium.executablePath()</code>.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Sub-Issue #857 — real Chrome Virtual Authenticator wiring + <code>/signin</code> credential assertion + Playwright e2e that exercises the register + signin round-trip end to end.</li><li>Sub-Issue #858 — userVerification 4 pattern (<code>required</code> / <code>preferred</code> / <code>discouraged</code> / <code>impossible</code>) + fidelity assertion on UV bit. <strong>Landed</strong> — see <code>webauthn-passkey-app-user-verification.md</code> for the UV bit fidelity table.</li><li>Sub-Issue #859 — <code>residentKey=required</code> discoverable credential + <code>/manage</code> route + release gate 7 axes.</li></ul>',11)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
